/// 进场曲线：0→62% 冲到 `1 + peek`（略过目标位），62%→100% 再回落到 1。
///
/// uni 的 `picker-panel-in` 是 0%:115% → 62%:**-3px** → 100%:0，两段各带一条 cubic-bezier。
/// 这里把「-3px」换成按面板自身高度取的比例：700px 的弹层约 3.5px，小对话框只有零点几像素
/// （动作幅度跟着体量走，不会在小面板上显得突兀）。
class YmSheetInCurve extends Curve {
  const YmSheetInCurve();

  /// 尾段超出量（占滑动距离的比例）。
  static const double peek = 0.005;

  /// 第一段结束的位置（uni 的 62%）。
  static const double breakAt = 0.62;

  @override
  double transformInternal(double t) {
    if (t >= 1) return 1;
    if (t < breakAt) {
      final k = const Cubic(0.22, 0.5, 0.2, 0.99).transform(t / breakAt);
      return k * (1 + peek);
    }
    final k = const Cubic(0.4, 0, 0.2, 1).transform((t - breakAt) / (1 - breakAt));
    return (1 + peek) - peek * k;
  }
}

